// Import-script contract: the SQL generated by import-usage-state.mjs from a
// synthetic usage-state.json, applied to D1, must reproduce the numbers the
// real scripts/report-usage.mjs computes from the same state. Expired
// installations may only become cumulative counters. Storage resets between
// tests, so the import runs inside each case.
import { describe, expect, it } from "vitest";
import { env } from "cloudflare:test";
import { buildStats } from "../src/stats.js";
import { analyticsDayKey } from "../src/util.js";
import { resetStats } from "./helpers.js";

const importCase = JSON.parse(env.CONTRACT_IMPORT);

const COMPARED_METRICS = [
  "knownInstallationInstances",
  "reportedFirstLaunches",
  "dailyActiveInstalls",
  "activeInstalls7d",
  "activeInstalls30d",
  "downloadsByFile",
  "downloadsByRef",
  "totalDownloadRequests",
  "totalDesktopDownloadRequests",
  "totalExtensionDownloadRequests",
  "totalOtherDownloadRequests",
  "pageViewsByPath",
  "totalPageViews",
  "totalHomePageViews",
  "homeToDownloadRate",
];

async function applyImport() {
  await resetStats();
  const statements = importCase.sql
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("--"));
  expect(statements.length).toBeGreaterThan(0);
  await env.STATS.batch(statements.map((statement) => env.STATS.prepare(statement)));
  return statements;
}

describe("import-usage-state.mjs", () => {
  it("generated SQL for the synthetic state", () => {
    expect(importCase.sql).toContain("INSERT INTO installs");
    expect(importCase.sql).toContain("'pre-edge'");
    expect(importCase.expected.knownInstallationInstances).toBe(3);
  });

  it("applies cleanly and reproduces the report-usage numbers", async () => {
    await applyImport();
    const workerStats = await buildStats(env.STATS, Date.now());
    const mismatched = [];
    for (const metric of COMPARED_METRICS) {
      try {
        expect(workerStats[metric], metric).toEqual(importCase.expected[metric]);
      } catch {
        mismatched.push(`${metric}: worker=${JSON.stringify(workerStats[metric])} nginx=${JSON.stringify(importCase.expected[metric])}`);
      }
    }
    expect(mismatched).toEqual([]);
  });

  it("kept expired installations only as cumulative counters", async () => {
    await applyImport();
    const installs = (await env.STATS.prepare("SELECT install_id, last_seen_at FROM installs ORDER BY install_id").all()).results;
    // Only the live installation (last seen 5 days ago) is a row.
    expect(installs.length).toBe(1);
    expect(Date.now() - installs[0].last_seen_at).toBeLessThan(10 * 24 * 3600 * 1000);

    const folded = (await env.STATS.prepare("SELECT key, count FROM counters WHERE kind = 'install_total'").all()).results;
    expect(folded).toEqual([{ key: "all", count: 2 }]);
    const firstLaunchFolded = (await env.STATS.prepare("SELECT count FROM counters WHERE kind = 'install_first_launch'").all()).results;
    expect(firstLaunchFolded).toEqual([{ count: 1 }]);
  });

  it("kept the recent daily sets and the imported per-day trend totals", async () => {
    await applyImport();
    const dailyRows = (await env.STATS.prepare("SELECT day FROM daily_active").all()).results.map((row) => row.day);
    expect(dailyRows).toEqual([analyticsDayKey(importCase.t0 - 3 * 24 * 3600 * 1000)]);

    const stats = await buildStats(env.STATS, Date.now());
    const recentDay = analyticsDayKey(importCase.t0 - 3 * 24 * 3600 * 1000);
    const trendRow = stats.daily.find((row) => row.date === recentDay);
    expect(trendRow).toBeTruthy();
    expect(trendRow.downloadRequests).toBe(4);
    expect(trendRow.pageViews).toBe(6);
    expect(trendRow.homePageViews).toBe(4);
    expect(trendRow.activeInstalls).toBe(1);
    expect(trendRow.firstLaunches).toBe(1);
  });

  it("marks the import and leaves the page-view switchover note out", async () => {
    await applyImport();
    const marker = await env.STATS.prepare("SELECT 1 AS marker FROM counters WHERE kind = 'import' LIMIT 1").first();
    expect(marker).toBeTruthy();
    const stats = await buildStats(env.STATS, Date.now());
    expect(stats.migratedFromLegacy).toBe(true);
    // No real-day edge page counters exist in this dataset.
    expect(stats.metricsNote).toBeUndefined();
  });
});
